import { cacheLife, cacheTag } from 'next/cache'

import { getPosts } from '@/lib/api'

export default async function BlogPostsPage() {
  'use cache'

  cacheLife({ revalidate: 60 * 60 })
  cacheTag('posts')

  const posts = await getPosts()

  return (
    <main
      style={{
        maxWidth: 760,
        margin: '0 auto',
        padding: '64px 24px',
        fontFamily:
          'Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
      }}
    >
      <h1 style={{ marginBottom: 32, fontSize: 40, lineHeight: 1.1 }}>
        Blog Posts
      </h1>
      <ul style={{ display: 'grid', gap: 16, margin: 0, padding: 0 }}>
        {posts.map((post) => (
          <li
            key={post.id}
            style={{
              display: 'block',
              border: '1px solid #d8dee4',
              borderRadius: 8,
              padding: 20,
            }}
          >
            <article>
              <h2 style={{ margin: '0 0 8px', fontSize: 22 }}>
                {post.title}
              </h2>
              <p style={{ margin: 0, color: '#57606a' }}>By {post.author}</p>
            </article>
          </li>
        ))}
      </ul>
    </main>
  )
}

